use std::fs::{self, OpenOptions};
use std::io::{self, Write};
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

static SEQ: AtomicU64 = AtomicU64::new(0);

pub fn commit(dest: &str, card: &[u8]) -> io::Result<()> {
    let path = Path::new(dest);
    let parent = path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "destination has no parent"))?;
    let name = path.file_name().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "destination has no name"))?;

    for _ in 0..100 {
        let n = SEQ.fetch_add(1, Ordering::Relaxed);
        let tmp = parent.join(format!(".{}.{}.{}.tmp", name.to_string_lossy(), std::process::id(), n));
        let mut file = match OpenOptions::new().write(true).create_new(true).open(&tmp) {
            Ok(f) => f,
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        };
        let result = (|| {
            file.write_all(card)?;
            file.sync_all()?;
            fs::rename(&tmp, path)?;
            FileSync::sync_dir(parent)
        })();
        if result.is_err() {
            let _ = fs::remove_file(&tmp);
        }
        return result;
    }
    Err(io::Error::new(io::ErrorKind::AlreadyExists, "unable to allocate temporary file"))
}

struct FileSync;
impl FileSync {
    fn sync_dir(path: &Path) -> io::Result<()> {
        fs::File::open(path)?.sync_all()
    }
}

pub fn release() {}
EOF
